steps.script:
var p = PhaseManager.get_current_phase_instance()
for i in range(4):
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	if str(w.get("window_id", "")) != "movement_phase_start":
		break
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return p != null and not p.has_pending_stratagem_window()

# Every token, letter Label and objective label reads upright on screen;
# round bases follow the token frame, irregular bases keep board facing.
var m = tree.root.get_node("Main")
var vr: float = m.view_rotation
var n_round = 0
var n_irr = 0
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if not t.has_method("_draw_rot") or t.base_shape == null:
		continue
	var screen_rot = t.get_global_transform_with_canvas().get_rotation()
	if absf(angle_difference(screen_rot, 0.0)) > 0.01:
		return "%s/%s token screen rotation %f" % [t.get_meta("unit_id"), t.get_meta("model_id"), screen_rot]
	var lbl = t.get_node_or_null("Label")
	if lbl != null and absf(angle_difference(lbl.get_global_transform_with_canvas().get_rotation(), 0.0)) > 0.01:
		return "%s label not upright" % t.get_meta("unit_id")
	var model_rot = float(t.model_data.get("rotation", 0.0))
	# On-screen base rotation = token screen rotation (0) + draw rotation.
	var want = model_rot if t.base_shape.get_type() == "circular" else model_rot + vr
	if absf(angle_difference(t._draw_rot(), want)) > 0.01:
		return "%s base draw rot %f want %f" % [t.get_meta("unit_id"), t._draw_rot(), want]
	if t.base_shape.get_type() == "circular":
		n_round += 1
	else:
		n_irr += 1
var n_obj = 0
for o in m.find_children("*", "ObjectiveVisual", true, false):
	for ch in o.get_children():
		if ch is Label:
			if absf(angle_difference(ch.get_global_transform_with_canvas().get_rotation(), 0.0)) > 0.01:
				return "%s label %s not upright" % [o.name, ch.name]
			n_obj += 1
return "ok round=%d irregular=%d objective_labels=%d rot=%d" % [n_round, n_irr, n_obj, int(round(rad_to_deg(vr))) % 360]

