# The oval Caladius: its letter/name stays under the base ON SCREEN, and its
# footprint keeps its board facing (screen rotation = model rot + board rot).
var m = tree.root.get_node("Main")
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if str(t.get_meta("unit_id", "")) == "U_CALADIUS_GRAV-TANK_E":
		var screen_center = t.get_global_transform_with_canvas().origin
		var lbl = t.get_node("Label")
		var lbl_top = lbl.get_global_transform_with_canvas().origin.y
		var base_rot_screen = t.get_global_transform_with_canvas().get_rotation() + t._draw_rot()
		var board_rot = float(t.model_data.get("rotation", 0.0)) + m.view_rotation
		return [t.base_shape.get_type(), lbl_top > screen_center.y, absf(angle_difference(base_rot_screen, board_rot)) < 0.01]
return "missing"

